-- Every timestamp below is written without a zone and means Singapore local time. The app stores
-- UTC and shows Asia/Singapore (DR3 in docs/specs/venue-booking-request.md), so read them as
-- Singapore time; without this, Postgres would take them as UTC and they would show 8 hours late.
set timezone = 'Asia/Singapore';

-- ============================================================================
-- AUTH USERS
-- ============================================================================
-- Inserted directly into auth.users so seeded accounts can log in locally.
-- All seeded accounts share the password 'ConnectSphere2026!'. This is a
-- development convenience, never use this pattern to create real accounts,
-- production sign-ups must go through Supabase Auth.

-- SCRUM-75: two Event Coordinator Leads, and a deactivated Event Coordinator (linked to a Lead, for the Lead's overview).

-- GoTrue reads these token columns as non-null strings; left NULL, every sign-in fails with
-- "Database error querying schema". Real sign-ups get '' from GoTrue itself.
update auth.users set
  confirmation_token         = coalesce(confirmation_token, ''),
  recovery_token             = coalesce(recovery_token, ''),
  email_change_token_new     = coalesce(email_change_token_new, ''),
  email_change_token_current = coalesce(email_change_token_current, ''),
  email_change               = coalesce(email_change, ''),
  phone_change               = coalesce(phone_change, ''),
  phone_change_token         = coalesce(phone_change_token, ''),
  reauthentication_token     = coalesce(reauthentication_token, '');

