  ('7a3d2590-ecb7-58ba-9204-a8b782379f0e', 'ee0d433e-a9a9-5ce2-af58-9d0541e236db', '7994c3f8-246c-5b7a-bb92-0767cea6a073', NULL, 'Returning this request, could you confirm expected attendance before we proceed to venue search?', '2026-07-31 10:00:00'),
  ('a71c98b9-c3ec-59fd-bef6-d39fa2f3f488', '11176b94-e34e-594c-8e17-bc445e88961c', '7994c3f8-246c-5b7a-bb92-0767cea6a073', NULL, 'This is the second follow-up on expected attendance, we will need to close this request if we do not hear back by Friday.', '2026-09-13 09:00:00'),
